CREATE TABLE public."Evaluation_Questions" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, image_url text NOT NULL DEFAULT '', options jsonb NOT NULL DEFAULT '[]', correct_option integer NOT NULL DEFAULT 0, points numeric NOT NULL DEFAULT 0 CHECK(points>=0), difficulty text NOT NULL DEFAULT 'medium', classification text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public."Evaluation_Questions" TO service_role; ALTER TABLE public."Evaluation_Questions" ENABLE ROW LEVEL SECURITY;
CREATE TABLE public."Evaluation_Templates" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), module text NOT NULL CHECK(module IN ('public_service','notebook')), title text NOT NULL, description text NOT NULL DEFAULT '', team_ids text[] NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, starts_at timestamptz, ends_at timestamptz, recurrence text NOT NULL DEFAULT 'activity', max_points numeric CHECK(max_points>=0), criteria jsonb NOT NULL DEFAULT '[]', created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public."Evaluation_Templates" TO service_role; ALTER TABLE public."Evaluation_Templates" ENABLE ROW LEVEL SECURITY;
CREATE TABLE public."Evaluation_Settings" (id text PRIMARY KEY DEFAULT 'main', config jsonb NOT NULL DEFAULT '{}', updated_by text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public."Evaluation_Settings" TO service_role; ALTER TABLE public."Evaluation_Settings" ENABLE ROW LEVEL SECURITY;
CREATE TABLE public."Evaluation_Attendance_Drafts" (activity_id uuid NOT NULL REFERENCES public."Evaluation_Activities"(id), user_id text NOT NULL, status text NOT NULL CHECK(status IN ('Present','Absent','Excused')), notes text NOT NULL DEFAULT '', recorded_by text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(activity_id,user_id)); GRANT ALL ON public."Evaluation_Attendance_Drafts" TO service_role; ALTER TABLE public."Evaluation_Attendance_Drafts" ENABLE ROW LEVEL SECURITY;
CREATE TABLE public."Evaluation_Changes" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_type text NOT NULL, entity_id text NOT NULL, actor_id text NOT NULL, action text NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT ON public."Evaluation_Changes" TO service_role; ALTER TABLE public."Evaluation_Changes" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Evaluation_Activities" ADD COLUMN publish_at timestamptz, ADD COLUMN closed_at timestamptz, ADD COLUMN image_url text NOT NULL DEFAULT '', ADD COLUMN template_id uuid REFERENCES public."Evaluation_Templates"(id), ADD COLUMN max_points numeric CHECK(max_points>=0), ADD COLUMN reveal_answers text NOT NULL DEFAULT 'closed', ADD COLUMN finalized_at timestamptz, ADD COLUMN linked_record text NOT NULL DEFAULT '';
ALTER TABLE public."Evaluation_Criteria" ADD COLUMN question_id uuid REFERENCES public."Evaluation_Questions"(id), ADD COLUMN description text NOT NULL DEFAULT '', ADD COLUMN image_url text NOT NULL DEFAULT '';
ALTER TABLE public."Evaluation_Results" ADD COLUMN criteria_snapshot jsonb NOT NULL DEFAULT '[]', ADD COLUMN notes text NOT NULL DEFAULT '';
CREATE UNIQUE INDEX points_once_per_activity ON public."Points_Transactions"(activity_id,user_id) WHERE activity_id IS NOT NULL AND module<>'adjustment'; CREATE INDEX evaluation_results_user ON public."Evaluation_Results"(user_id,activity_id);